import java.util.*;
class DivideByZeroException extends Exception {DivideByZeroException(String m){super(m);}}
public class GuardedCalculator {public static void main(String[] args){Scanner sc=new Scanner(System.in);boolean done=false;while(!done){try{System.out.print("First number: ");double a=Double.parseDouble(sc.next());System.out.print("Operator: ");String op=sc.next();System.out.print("Second number: ");double b=Double.parseDouble(sc.next());if(op.equals("/")&&b==0)throw new DivideByZeroException("Cannot divide by zero");double result=switch(op){case "+"->a+b;case "-"->a-b;case "*"->a*b;case "/"->a/b;default->throw new IllegalArgumentException("Invalid operator");};System.out.println("Result: "+result);done=true;}catch(NumberFormatException e){System.out.println("Invalid number");}catch(DivideByZeroException|IllegalArgumentException e){System.out.println(e.getMessage());}finally{System.out.println("Calculation attempt finished");}}}}
